package dk.stream.android;
import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;
public class TvFavoritesTest {
 private Library.Entry entry(String name,String url){return new Library.Entry("source",new Playlist.Channel(name,"https://example.com/"+url,"Group",Playlist.Kind.TV,null));}
 @Test public void oldTvFavoritesRemainOnTvOne(){Library library=new Library();Library.Entry channel=entry("DR1","one");library.toggleFavorite(channel);assertEquals(1,TvFavorites.mask(library,channel));assertEquals(1,TvFavorites.list(library,0).size());assertTrue(TvFavorites.list(library,1).isEmpty());}
 @Test public void newBackupDoesNotAppearOnTvOne(){Library library=new Library();Library.Entry channel=entry("DR1","backup");TvFavorites.add(library,channel,2);assertEquals(4,TvFavorites.mask(library,channel));assertTrue(FavoriteLists.items(library,"Streaming").isEmpty());assertEquals(1,FavoriteLists.items(library,"TV 3").size());}
 @Test public void channelCanBelongToAllFourLists(){Library library=new Library();Library.Entry channel=entry("DR1","one");for(int index=0;index<4;index++)TvFavorites.add(library,channel,index);assertEquals(1,library.favorites.size());assertEquals(15,TvFavorites.mask(library,channel));for(int index=0;index<4;index++)assertEquals(1,TvFavorites.list(library,index).size());}
 @Test public void removingOneMembershipPreservesTheOtherLists(){Library library=new Library();Library.Entry channel=entry("DR1","one");TvFavorites.set(library,channel,15);TvFavorites.remove(library,channel,0);assertTrue(library.isFavorite(channel));assertEquals(14,TvFavorites.mask(library,channel));assertTrue(FavoriteLists.items(library,"Streaming").isEmpty());TvFavorites.set(library,channel,0);assertFalse(library.isFavorite(channel));assertTrue(library.tvFavoriteLists.isEmpty());}
 @Test public void skipsMissingNamesAndReturnsToPrimary(){Library library=new Library();Library.Entry primary=entry(" DR1 ","one"),other=entry("DR2","two"),backup=entry("dr1","three");TvFavorites.add(library,primary,0);TvFavorites.add(library,other,1);TvFavorites.add(library,backup,2);TvFavorites.Match match=TvFavorites.next(library,primary,0,primary.channel.url);assertEquals(2,match.index);assertSame(backup,match.entry);match=TvFavorites.next(library,primary,2,backup.channel.url);assertEquals(0,match.index);assertSame(primary,match.entry);assertSame(primary,TvFavorites.list(library,0).get(0));}
 @Test public void skipsIdenticalStreamUrls(){Library library=new Library();Library.Entry channel=entry("DR1","one");TvFavorites.set(library,channel,15);assertNull(TvFavorites.next(library,channel,0,channel.channel.url));}
 @Test public void groupOrderIsPreservedEvenForExistingFavorites(){Library library=new Library();Library.Entry existing=entry("Existing","keep"),one=entry("One","one"),two=entry("Two","two"),three=entry("Three","three");TvFavorites.add(library,existing,1);TvFavorites.add(library,three,1);TvFavorites.add(library,one,1);TvFavorites.addGroup(library,Arrays.asList(one,two,three),1);assertEquals(Arrays.asList(existing,one,two,three),TvFavorites.list(library,1));assertEquals(4,library.favorites.size());}
 @Test public void listMembershipSurvivesExportAndImport()throws Exception{Library library=new Library();Library.Source source=Library.Source.m3u("Source","https://example.com/list.m3u");library.sources.add(source);Library.Entry channel=new Library.Entry(source.id,new Playlist.Channel("DR1","https://example.com/one",""));TvFavorites.set(library,channel,13);Library restored=SettingsBackup.decode(new java.io.ByteArrayInputStream(SettingsBackup.encode(library)));assertEquals(13,TvFavorites.mask(restored,restored.favorites.get(0)));assertEquals(1,TvFavorites.list(restored,0).size());assertTrue(TvFavorites.list(restored,1).isEmpty());assertEquals(1,TvFavorites.list(restored,2).size());assertEquals(1,TvFavorites.list(restored,3).size());}
 @Test public void sourceRefreshKeepsMembershipAndRemovalClearsIt(){Library library=new Library();Library.Source source=Library.Source.m3u("Source","https://example.com/list");library.sources.add(source);Library.Entry old=new Library.Entry(source.id,new Playlist.Channel("DR1","https://example.com/old",""));TvFavorites.set(library,old,10);library.refreshFavorites(source.id,Arrays.asList(new Playlist.Channel("DR1","https://example.com/new","")));assertEquals(10,TvFavorites.mask(library,library.favorites.get(0)));library.removeSource(source.id);assertTrue(library.tvFavoriteLists.isEmpty());}
 @Test public void restartResolvesBackupOrOldLinkToTvOne(){Library library=new Library();Library.Entry primary=entry("DR1","primary"),backup=entry("DR1","backup");TvFavorites.add(library,primary,0);TvFavorites.add(library,backup,1);assertSame(primary,TvFavorites.primary(library,backup.channel));assertSame(primary,TvFavorites.primary(library,new Playlist.Channel("DR1","https://example.com/old-primary","")));}
 @Test public void groupOrderSurvivesExport()throws Exception{Library library=new Library();Library.Source source=Library.Source.m3u("Source","https://example.com/list");library.sources.add(source);List<Library.Entry> group=new ArrayList<>();for(String name:Arrays.asList("DR2","DR1","TV2"))group.add(new Library.Entry(source.id,new Playlist.Channel(name,"https://example.com/"+name,"Group")));TvFavorites.addGroup(library,group,3);Library restored=SettingsBackup.decode(new java.io.ByteArrayInputStream(SettingsBackup.encode(library)));List<Library.Entry> actual=TvFavorites.list(restored,3);assertEquals(3,actual.size());assertEquals("DR2",actual.get(0).channel.name);assertEquals("DR1",actual.get(1).channel.name);assertEquals("TV2",actual.get(2).channel.name);assertTrue(TvFavorites.list(restored,0).isEmpty());}

}
